create or replace function public.record_franchise_distribution_payout(p_book_id uuid,p_beneficiary_code text,p_amount_minor bigint,p_financial_journal_id uuid,p_reference text,p_proof_hash text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
