if j.journal_type<>'FRANCHISE_DISTRIBUTION_PAYOUT' or p_amount_minor is distinct from(select coalesce(sum(case when entry.direction='DEBIT'then entry.amount_minor else-entry.amount_minor end),0)from public.financial_entries entry join public.financial_accounts account on account.id=entry.account_id where entry.journal_id=j.id and account.account_type='LIABILITY') or p_amount_minor is distinct from(select coalesce(sum(case when entry.direction='CREDIT'then entry.amount_minor else-entry.amount_minor end),0)from public.financial_entries entry join public.financial_accounts account on account.id=entry.account_id where entry.journal_id=j.id and account.account_type='ASSET')then raise exception 'FRANCHISE_PAYOUT_SOURCE_MISMATCH'using errcode='23514';end if;
