create or replace function public.post_franchise_pnl_entry(p_book_id uuid,p_effect_type text,p_category text,p_amount_minor bigint,p_financial_journal_id uuid,p_source_type text,p_source_id text,p_effective_on date,p_reason text,p_reverses_entry_id uuid,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();b public.franchise_pnl_books%rowtype;j public.financial_journals%rowtype;x public.franchise_pnl_entries%rowtype;h text;r jsonb;e uuid;begin select * into b from public.franchise_pnl_books where id=p_book_id;select * into j from public.financial_journals where id=p_financial_journal_id;if a is null or b.id is null or not private.has_platform_role(array['SUPER_ADMIN','FINANCE_MANAGER'],a)or auth.jwt()->>'aal'<>'aal2'then raise exception 'FRANCHISE_PNL_POST_DENIED'using errcode='42501';end if;if p_amount_minor is null or p_effect_type is null or p_category is null or p_effective_on is null or b.status<>'OPEN'or p_effect_type not in('REVENUE','COST','REVERSAL_REVENUE','REVERSAL_COST')or p_category not in('COLLECTED_NET_REVENUE','REFUND_CREDIT_NOTE','PROVIDER_FULFILLMENT_COST','VOLUME_CONTRACT_COST','PAYMENT_FEE','DIRECT_MARKETING_COST','APPROVED_DIRECT_OTHER_COST','APPROVED_SHARED_CENTRAL_COST')or p_amount_minor<=0 or j.id is null or j.organization_id<>b.franchise_organization_id or j.currency<>b.currency or j.status<>'POSTED'or length(btrim(coalesce(p_reason,'')))not between 3 and 1000 then raise exception 'INVALID_FRANCHISE_PNL_ENTRY'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('book',b.id,'effect',p_effect_type,'category',p_category,'amount',p_amount_minor,'journal',j.id,'source_type',p_source_type,'source_id',p_source_id,'effective_on',p_effective_on,'reason',p_reason,'reverses',p_reverses_entry_id));r:=private.begin_contract_command(b.franchise_organization_id,'franchise.pnl.post.'||b.id::text,p_idempotency_key,h,a);if r is not null then return r;end if;perform pg_advisory_xact_lock(hashtextextended('franchise.pnl.journal.'||j.id::text,0));
if j.created_by=a then raise exception 'FRANCHISE_INDEPENDENT_REVIEW_REQUIRED'using errcode='42501';end if;
