-- collected, earned, net-of-tax revenue. Native credit allocations use their
-- private source-bound bridge and still face the cost-reconciliation close guard.
if p_effect_type='REVENUE' then raise exception 'FRANCHISE_NATIVE_REVENUE_RECONCILIATION_REQUIRED'using errcode='55000';end if;
if p_source_type is distinct from 'FINANCIAL_JOURNAL' or p_source_id is distinct from j.id::text or p_effective_on is distinct from(j.effective_at at time zone 'Africa/Casablanca')::date then raise exception 'FRANCHISE_PNL_SOURCE_MISMATCH'using errcode='23514';end if;
if p_amount_minor is distinct from(select coalesce(sum(case when(p_effect_type='COST'and entry.direction='DEBIT')or(p_effect_type='REVERSAL_COST'and entry.direction='CREDIT')or(p_effect_type='REVERSAL_REVENUE'and entry.direction='DEBIT')then entry.amount_minor else-entry.amount_minor end),0)from public.financial_entries entry join public.financial_accounts account on account.id=entry.account_id where entry.journal_id=j.id and account.account_type=case when p_effect_type='REVERSAL_REVENUE'then'REVENUE'else'EXPENSE'end)then raise exception 'FRANCHISE_PNL_NET_AMOUNT_MISMATCH'using errcode='23514';end if;
if exists(select 1 from public.franchise_pnl_entries where financial_journal_id=j.id) then raise exception 'FRANCHISE_PNL_JOURNAL_ALREADY_USED'using errcode='23514';end if;
if p_effect_type in('REVERSAL_REVENUE','REVERSAL_COST')then select * into x from public.franchise_pnl_entries where id=p_reverses_entry_id and book_id=b.id;if not found or x.category is distinct from p_category or x.currency is distinct from b.currency or x.amount_minor<>p_amount_minor or(p_effect_type='REVERSAL_REVENUE'and x.effect_type<>'REVENUE')or(p_effect_type='REVERSAL_COST'and x.effect_type<>'COST')or exists(select 1 from public.franchise_pnl_entries where reverses_entry_id=x.id)then raise exception 'INVALID_PNL_REVERSAL'using errcode='22023';end if;elsif p_reverses_entry_id is not null then raise exception 'INVALID_PNL_REVERSAL'using errcode='22023';end if;insert into public.franchise_pnl_entries(book_id,effect_type,category,amount_minor,currency,financial_journal_id,source_type,source_id,effective_on,reason,reverses_entry_id,correlation_id,created_by)values(b.id,p_effect_type,p_category,p_amount_minor,b.currency,j.id,p_source_type,p_source_id,p_effective_on,p_reason,p_reverses_entry_id,p_correlation_id,a)returning id into e;r:=jsonb_build_object('outcome','FRANCHISE_PNL_ENTRY_POSTED','entry_id',e,'book_id',b.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(b.franchise_organization_id,a,'USER','franchise.pnl_entry.posted','franchise_pnl_entry',e::text,p_correlation_id,jsonb_build_object('category',p_category,'amount_minor',p_amount_minor,'effect_type',p_effect_type),repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(b.franchise_organization_id,'franchise_pnl_book',b.id::text,'FranchisePnlEntryPostedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(b.franchise_organization_id,'franchise.pnl.post.'||b.id::text,p_idempotency_key,r);return r;end$$;

